import { requestSignal } from "resilience-kit/express"; // only uses Node http types
import { mapResilienceError } from "resilience-kit";

export const signalOf = (request, reply) => requestSignal(request.raw, reply.raw);

export function registerResilienceErrors(app) {
  const previous = app.errorHandler;
  app.setErrorHandler((error, request, reply) => {
    const m = mapResilienceError(error);
    if (m === undefined || reply.sent) return previous(error, request, reply);
    reply.code(m.status).headers(m.headers).send(m.body);
  });
}

